@@ -30,3 +38,28 @@ export function t(key, lang = "en", params = {}) {

 /** Message keys per language, for checks. */
 export const messageKeys = (lang) => Object.keys(MESSAGES[lang] ?? {});
+
+/** Picks a supported language (`en` or `ko`) from an `Accept-Language` header. */
+export function pickLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const candidates = [];
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    if (!rawTag) continue;
+    const lang = rawTag.trim().split(/[-_]/)[0].toLowerCase();
+    if (!LANGUAGES.includes(lang)) continue;
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const [k, v] = p.split("=").map((s) => s.trim());
+      if (k.toLowerCase() === "q") {
+        q = Number(v);
+        if (!v || !Number.isFinite(q) || q <= 0 || q > 1) valid = false;
+      }
+    }
+    if (valid) candidates.push({ lang, q });
+  }
+  if (!candidates.length) return fallback;
+  candidates.sort((a, b) => b.q - a.q);
+  return candidates[0].lang;
+}
